	port.AssertEq(emonT, plan.RqArg(c, 0, 6), 40, "region height")
	port.AssertEq(emonT, plan.RqArg(c, 0, 7), 1701734144, "eng packed big-endian")
	port.AssertEq(emonT, plan.RqArg(c, 0, 8), 1684370688, "deu packed big-endian")
