func TestAnswersCarryTheIdAndAStatus(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var a1 int32 = plan.AnRender(c, 1, 612, 792, 1, 300)
	var a2 int32 = plan.AnFail(c, 2, 2, 1)
	var a3 int32 = plan.AnDecode(c, 3, 32, 16, 3, 7200, 0, 1)
	port.AssertEq(emonT, a1, 0, "first at 0")
	port.AssertEq(emonT, a2, 8, "second after the render's eight cells")
	port.AssertEq(emonT, a3, 12, "third after the four-cell failure")
	port.AssertEq(emonT, plan.AnStatus(c, a1), 0, "render ok")
	port.AssertEq(emonT, plan.AnArg(c, a1, 0), 612, "w")
	port.AssertEq(emonT, plan.AnArg(c, a1, 1), 792, "h")
	port.AssertEq(emonT, plan.AnArg(c, a1, 2), 1, "channels")
	port.AssertEq(emonT, plan.AnArg(c, a1, 3), 300, "dpi")
	port.AssertEq(emonT, plan.AnStatus(c, a2), 1, "decode failed")
	port.AssertEq(emonT, plan.AnOk(c, a2), 0, "not ok")
	port.AssertEq(emonT, plan.RecLen(c, a2), 4, "a failure is the header and a status")
	port.AssertEq(emonT, plan.AnArg(c, a3, 3), 7200, "dpi x100")
	port.AssertEq(emonT, plan.AnArg(c, a3, 5), 1, "frames")
	port.AssertEq(emonT, plan.RecCount(c), 3, "three records")
	port.AssertEq(emonT, plan.AnFind(c, 2), a2, "found by id")
	port.AssertEq(emonT, plan.AnFind(c, 4), -1, "an unasked id is not found")
	port.AssertEq(emonT, plan.RecNext(c, a1), a2, "walking")
}

func TestAnOcrAnswerHoldsWordsWithTheirText(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var at int32 = plan.AnOcr(c, 3)
	var w0 int32 = plan.AnOcrWord(c, at, 10, 20, 300, 40, 912, 0, 1)
	plan.AnOcrCp(c, w0, 72)
	plan.AnOcrCp(c, w0, 105)
	var w1 int32 = plan.AnOcrWord(c, at, 400, 20, 50, 40, 870, 0, 1)
	plan.AnOcrCp(c, w1, 128512)
	plan.AnOcrEnd(c, at)
	port.AssertEq(emonT, plan.AnOcrCount(c, at), 2, "two words")
	port.AssertEq(emonT, plan.AnOcrFirst(c, at), 5, "the first word follows the count")
	port.AssertEq(emonT, plan.AnOcrFirst(c, at), w0, "and is w0")
	port.AssertEq(emonT, plan.AwGet(c, w0, plan.AwX()), 10, "x")
	port.AssertEq(emonT, plan.AwGet(c, w0, plan.AwConf()), 912, "confidence x10")
	port.AssertEq(emonT, plan.AwGet(c, w0, plan.AwLen()), 2, "two code points")
	port.AssertEq(emonT, plan.AwCp(c, w0, 1), 105, "i")
	port.AssertEq(emonT, plan.AwNext(c, w0), w1, "the next word")
	port.AssertEq(emonT, plan.AwCp(c, w1, 0), 128512, "a code point outside the BMP is one cell")
	port.AssertEq(emonT, plan.AwNext(c, w1), port.CellsLen(c), "and the last ends the record")
	port.AssertEq(emonT, plan.RecLen(c, at), port.CellsLen(c), "the record's length covers them")
}

func TestARecordWalkRefusesWhatIsMalformed(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var d *port.Cells = port.NewCells()
	var e *port.Cells = port.NewCells()
	var f *port.Cells = port.NewCells()
	plan.RqRender(c, 1, 0, 0, 72, 0)
	plan.RqRender(c, 2, 0, 1, 72, 0)
	port.AssertEq(emonT, plan.RecCheck(c, 1, 3), 0, "well formed")
	plan.RqRender(c, 2, 0, 2, 72, 0)
	port.AssertEq(emonT, plan.RecCheck(c, 1, 3), 4, "a repeated id")
	plan.RqBytes(d, 1, 0, 0, 1)
	port.AssertEq(emonT, plan.RecCheck(d, 1, 3), 2, "a bytes request is not one kin may make")
	port.AssertEq(emonT, plan.RecCheck(d, 1, 4), 0, "though it is a record")
	plan.RqRender(e, 0, 0, 0, 72, 0)
	port.AssertEq(emonT, plan.RecCheck(e, 1, 3), 3, "an id of 0")
	port.CellsPush(f, 9)
	port.CellsPush(f, 1)
	port.CellsPush(f, 1)
	port.AssertEq(emonT, plan.RecCheck(f, 1, 3), 1, "a length past the end")
	port.AssertEq(emonT, plan.RecCount(f), -1, "is not a run of records")
	port.AssertEq(emonT, plan.RecCount(port.NewCells()), 0, "nothing is zero records")
	port.AssertEq(emonT, plan.RecFind(port.NewCells(), 1), -1, "and finds nothing")
}

