func TestTheProbeAsksInTwoRoundsAndThenWritesEvidence(emonT *testing.T) {
	var s *port.Src = port.SrcOfBlob(port.TextBlob("0123456789abcdef"))
	var an *port.Cells = port.NewCells()
	var rq *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var t *strings.Builder = port.NewText()
	port.AssertEq(emonT, ptUnit(s, an, rq, et, t), 1, "round 0 asks")
	port.AssertEq(emonT, plan.RecCount(rq), 2, "for two things")
	port.AssertEq(emonT, plan.RecCheck(rq, 1, 3), 0, "well formed")
	port.AssertEq(emonT, plan.RecId(rq, 0), 1, "the render is id 1")
	port.AssertEq(emonT, plan.RecKind(rq, 0), 1, "a render")
	var second int32 = plan.RecNext(rq, 0)
	port.AssertEq(emonT, plan.RecKind(rq, second), 2, "and a decode")
	plan.AnRender(an, 1, 64, 48, 1, 300)
	plan.AnDecode(an, 2, 32, 16, 3, 7200, 0, 1)
	port.CellsDrop(rq, 0)
	port.AssertEq(emonT, ptUnit(s, an, rq, et, t), 1, "round 1 asks")
	port.AssertEq(emonT, plan.RecCount(rq), 2, "for two OCRs")
	port.AssertEq(emonT, plan.RecId(rq, 0), 3, "id 3")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 0), 1, "of the render's bitmap")
	var second4 int32 = plan.RecNext(rq, 0)
	port.AssertEq(emonT, plan.RecId(rq, second4), 4, "id 4")
	port.AssertEq(emonT, plan.RqArg(rq, second4, 0), 2, "of the decode's bitmap")
	var o3 int32 = plan.AnOcr(an, 3)
	var w int32 = plan.AnOcrWord(an, o3, 6, 3, 40, 9, 911, 0, 0)
	plan.AnOcrCp(an, w, 72)
	plan.AnOcrCp(an, w, 105)
	plan.AnOcrEnd(an, o3)
	plan.AnFail(an, 3, 4, 1)
	port.CellsDrop(rq, 0)
	port.AssertEq(emonT, ptUnit(s, an, rq, et, t), 0, "round 2 is done")
	port.AssertEq(emonT, port.CellsLen(rq), 0, "and asks for nothing")
}
